# prompts.py - picture prompts for sun-vanish (all gpt-image-2.5-sunburst, 1K, quality LOW, 1 variation, NO references)
# STYLE / CHARACTER / KEY / BG blocks word for word from memory/STYLE.md (the channel's locked look).
import json
CHAR = "Flat 2D cartoon: a simple white character with a big round head, a small soft body, noodle arms with simple four-finger hands and short legs with rounded feet, thick smooth black (#000000) outlines of even weight, about 2 % of the head width thick, flat white fill (#FEFDFD) with a very soft pale-grey shade (#EDEBEB) on the left side of the head and body, the round head is wider than the body and about 0.38 of the full body height, small solid black vertical oval eyes about one sixth of the head width tall, simple curved black eyebrows, no nose, no hair, no clothes, a pink tongue (#FC8D90) only when the mouth is open. Clean vector-like linework, flat colours, no texture, no text, no border."
# measured on the keyed hero: lens ~0.27 of the head width, outline ~2.2 % of the head width, fill #FCFCFC/#ECECEC
# this video's role add-on: sunglasses (worn over the eyes, or pushed up on the forehead)
GLASSES_ON = " This character is sunbathing: exactly the same simple white character, wearing only a pair of small cartoon sunglasses: two round solid black (#000000) lenses, each about one quarter of the head width across, joined by a short thin black bridge, with one thin black arm going back to the side of the head, worn over both eyes so the eyes are hidden - nothing else added, no hair, no clothes, no swimsuit."
GLASSES_UP = " Exactly the same simple white character, wearing only a pair of small cartoon sunglasses: two round solid black (#000000) lenses, each about one quarter of the head width across, joined by a short thin black bridge, pushed up high on the top of the head so both eyes are uncovered - nothing else added, no hair, no clothes, no swimsuit."
OBJ = "Flat 2D cartoon in the same drawing style: bold clean thick smooth black outlines of even weight, flat colours with one simple soft shade, clean vector-like linework, simple shapes, no texture, no text, no border, no characters."
def KEY(c='green'):
    col = 'pure green (#00FF00)' if c == 'green' else 'pure magenta (#FF00FF)'
    return f"Isolated on a perfectly flat, uniform, solid {col} background that fills the whole picture edge to edge: no shadow, no ground, no floor line, no gradient, no vignette, no border, no other objects. The whole subject in frame with a clear margin on every side."
BG = "Flat 2D cartoon background in the same drawing style: big simple flat-colour shapes, thick smooth black outlines only on the main shapes, no texture, no text, no labels, no arrows, no characters, calm and simple so a character reads clearly on top of it."
LYING = "Full body seen from the side, lying flat on the ground, the head on the LEFT side of the image and the feet on the RIGHT side, no towel, no ground drawn. "
COL3 = "Three DIFFERENT poses of the same character stacked one above the other in one column, all three the same size, with wide empty gaps between them, every copy full body seen from the side lying flat with the head on the LEFT side of the image and the feet on the RIGHT side, no towel, no ground drawn, bold clean thick outlines. "
ROW3 = "Three DIFFERENT poses of the same character side by side in one row, all three the same size, with wide empty gaps between them, every copy full body, no ground drawn, bold clean thick outlines. "
ROW2 = "Two DIFFERENT poses of the same character side by side in one row, both the same size, with a wide empty gap between them, both full body facing the viewer, no ground drawn, bold clean thick outlines. "

def tail(glasses):
    return " Whole bodies in frame with a margin. " + CHAR + glasses + " " + KEY()

P = {
 'hero': ("3:2", LYING + "Sunbathing on its back, totally relaxed: both hands folded behind the head, one knee bent up with the other leg resting straight, a calm happy closed-mouth smile, relaxed eyebrows above the sunglasses. Whole body in frame with a margin. Bold clean thick outlines. " + CHAR + GLASSES_ON + " " + KEY()),
 'lie3': ("2:3", COL3 + "TOP copy: lying on its back, the hand on the LEFT side of the image lifting the sunglasses up off the eyes to peek at the sky (the eyes visible under the raised sunglasses), puzzled face, one eyebrow raised, small flat mouth, the other arm resting on the belly. MIDDLE copy: rolling over, lying on its side facing the viewer, both arms tucked in front of the chest, knees slightly bent, sunglasses on, a happy closed-mouth smile. BOTTOM copy: lying on its belly, the chin resting on both folded arms, the feet kicked up in the air behind it, sunglasses on, a blissful closed-mouth smile." + tail(GLASSES_ON)),
 'react3': ("3:2", ROW3 + "LEFT copy: sitting up on the ground with the legs straight out to the RIGHT side of the image, shocked, leaning back on both hands, looking up, mouth wide open in a long vertical oval with the pink tongue showing, sunglasses on. MIDDLE copy: lying flat on its belly and holding on for dear life with both hands gripping the ground in front of the head, the whole body and legs blown out straight to the RIGHT side of the image as if by a huge wind, sunglasses on, teeth gritted, scared. RIGHT copy: sitting on the ground hugging both knees tightly to the chest, freezing and shivering, eyes wide, eyebrows tilted up in the middle, mouth a small wavy line, sunglasses on." + tail(GLASSES_ON)),
 'end2': ("3:2", ROW2 + "LEFT copy: standing and freezing cold, both arms wrapped tightly around its own body, shoulders hunched, knees together, chattering teeth: the mouth open in a wide flat rectangle showing two rows of white teeth, eyebrows tilted up in the middle, wide eyes. RIGHT copy: standing proud and smug, chest puffed out, both fists on the hips, chin up, a confident closed-mouth smile, eyes half closed, relaxed eyebrows." + tail(GLASSES_UP)),
 'props': ("3:2", "Three separate objects side by side in one row with wide empty gaps between them, all about the same height. LEFT: an open beach umbrella seen from the side, a wide dome canopy of six alternating red and white panels on a thin straight white pole, a small round tip on top. MIDDLE: a small plastic sunscreen bottle standing upright, orange body with a white flip cap, no text, no label. RIGHT: a small cute sandcastle of yellow sand with three little round towers and a tiny red flag on the middle tower. Bold clean thick outlines. " + OBJ + " " + KEY()),
 'beach': ("2:3", "A sunny beach seen from the side, vertical picture: a clear plain light-blue sky in the top 58 % of the picture with no sun and no clouds in its upper half and only two small flat white clouds low near the horizon; a calm blue sea band from about 58 % to 70 % of the height with a few simple short white wave lines; warm pale-yellow sand in the bottom 30 % with a gently curved front edge, a few tiny pebbles and one small shell near the bottom corners. No umbrella, no towel, no people, no animals, no boats, no text. Clean open sand in the lower middle where a character will lie. " + BG),
 'space': ("2:3", "Outer space, vertical picture: a flat deep navy-blue night sky filling the whole picture, scattered with many small simple white dots and a few small white four-point stars, one faint soft purple cloud swirl in the lower left corner and one faint teal cloud swirl in the upper right corner. No sun, no planets, no moon, no ships, no people, no text. Calm and simple. " + BG),
}
json.dump(P, open('prompts.json', 'w'), indent=1)
with open('prompts.md', 'w') as f:
    f.write('# sun-vanish - picture prompts (all gpt-image-2.5-sunburst, 1K, quality LOW, 1 variation, no references)\n\n')
    for k, (ar, p) in P.items(): f.write(f'## {k} ({ar})\n{p}\n\n')
for k, (ar, p) in P.items(): print(k, ar, len(p))
